    dim3 blocks((P + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y);

    // Launch kernel
    matmul_kernel<BLOCK_SIZE><<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

