# Define the custom CUDA kernel for optimized matrix multiplication
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// TILE_SIZE defines the size of the shared memory tile
// BLOCK_SIZE defines the number of threads per block
#define BLOCK_SIZE 16
#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block indices
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread indices within the block
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Each block computes one sub-matrix of C
    int row = blockRow * TILE_SIZE + threadRow;
    int col = blockCol * TILE_SIZE + threadCol;

    // Shared memory tiles for A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Accumulator for each thread
    float c_val = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile of A into shared memory
        int a_col = tile * TILE_SIZE + threadCol;
        if (row < N && a_col < N) {
            As[threadRow][threadCol] = A[row * N + a_col];
        } else {
            As[threadRow][threadCol] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = tile * TILE_SIZE + threadRow;
        if (b_row < N && col < N) {
            Bs[threadRow][threadCol] = B[b_row * N + col];
        } else {
            Bs[threadRow][threadCol] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_SIZE; k++) {
            c_val += As[threadRow][k] * Bs[k][threadCol];
        }

